import React, { useState } from 'react';
import { QUESTIONS, PLATFORM_QUESTIONS } from '../utils/questions';

export default function Questionnaire({ onSubmit }) {
  const [answers, setAnswers] = useState({});
  const [platformUsage, setPlatformUsage] = useState({
    instagram: 0,
    youtube: 0,
    tiktok: 0,
    twitter: 0,
    facebook: 0,
    snapchat: 0,
  });

  const [selfRating, setSelfRating] = useState(5);
  const [current, setCurrent] = useState(0);
  const [phase, setPhase] = useState('questions');

  const question = QUESTIONS?.[current];
  const totalQ = QUESTIONS.length;
  const answered = Object.keys(answers).length;

  const selectAnswer = (qId, score) => {
    if (!qId) return;

    setAnswers((prev) => ({
      ...prev,
      [String(qId)]: score,
    }));

    setTimeout(() => {
      if (current < totalQ - 1) {
        setCurrent((c) => c + 1);
      } else {
        setPhase('platform');
      }
    }, 200);
  };

  // ✅ FIXED SUBMIT — no blocking validation since review phase means all done
  const handleSubmit = () => {
    onSubmit({
      answers,
      platformUsage,
      selfRating,
    });
  };

  const progress =
    phase === 'questions'
      ? Math.round((answered / totalQ) * 100)
      : phase === 'platform'
      ? 75
      : phase === 'selfrating'
      ? 90
      : 100;

  return (
    <div className="max-w-2xl mx-auto">

      {/* PROGRESS */}
      <div className="mb-6">
        <div className="flex justify-between text-sm text-white/40">
          <span>Progress</span>
          <span>{progress}%</span>
        </div>
        <div className="h-2 bg-white/10 rounded">
          <div
            className="h-full bg-brand-500 rounded"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* ================= QUESTIONS ================= */}
      {phase === 'questions' && question && (
        <div className="card">
          <h2 className="text-white text-xl mb-6">
            Q{current + 1}. {question.text}
          </h2>

          <div className="space-y-3">
            {question.options.map((opt, i) => {
              const selected = answers[String(question.id)] === opt.score;

              return (
                <button
                  key={i}
                  onClick={() => selectAnswer(question.id, opt.score)}
                  className={`w-full text-left p-4 rounded-lg border ${
                    selected
                      ? 'bg-brand-500 text-white'
                      : 'bg-surface text-white/70'
                  }`}
                >
                  {opt.label}
                </button>
              );
            })}
          </div>

          <div className="flex gap-3 mt-6">
            <button
              disabled={current === 0}
              onClick={() => setCurrent((c) => c - 1)}
              className="btn-secondary flex-1"
            >
              Back
            </button>

            <button
              disabled={!answers[String(question.id)]}
              onClick={() => {
                if (current < totalQ - 1) {
                  setCurrent((c) => c + 1);
                } else {
                  setPhase('platform');
                }
              }}
              className="btn-primary flex-1"
            >
              Next
            </button>
          </div>
        </div>
      )}

      {/* ================= PLATFORM ================= */}
      {phase === 'platform' && (
        <div className="card">
          <h2 className="text-white text-xl mb-6">
            Platform Usage
          </h2>

          {PLATFORM_QUESTIONS.map((p) => (
            <div key={p.id} className="mb-4">
              <label className="text-white">{p.label}</label>
              <input
                type="range"
                min="0"
                max="10"
                value={platformUsage[p.id]}
                onChange={(e) =>
                  setPlatformUsage((prev) => ({
                    ...prev,
                    [p.id]: Number(e.target.value),
                  }))
                }
                className="w-full"
              />
            </div>
          ))}

          <button
            onClick={() => setPhase('selfrating')}
            className="btn-primary w-full mt-4"
          >
            Next
          </button>
        </div>
      )}

      {/* ================= SELF RATING ================= */}
      {phase === 'selfrating' && (
        <div className="card">
          <h2 className="text-white text-xl mb-6">
            Self Rating
          </h2>

          <input
            type="range"
            min="1"
            max="10"
            value={selfRating}
            onChange={(e) => setSelfRating(Number(e.target.value))}
            className="w-full"
          />

          <p className="text-white text-center mt-2">
            {selfRating}/10
          </p>

          <button
            onClick={() => setPhase('review')}
            className="btn-primary w-full mt-4"
          >
            Next
          </button>
        </div>
      )}

      {/* ================= REVIEW ================= */}
      {phase === 'review' && (
        <div className="card">
          <h2 className="text-white text-xl mb-4">
            Final Step
          </h2>

          <p className="text-white/60 mb-6">
            Click below to analyze your social media impact.
          </p>

          <button
            onClick={handleSubmit}
            className="btn-primary w-full"
          >
            Analyze My Score
          </button>
        </div>
      )}
    </div>
  );
}
